/*
 * A037354  Numbers whose base-4 and base-7 expansions have no digits in
 *          common.
 * https://oeis.org/A037354
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 59, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   no_common_digits_idx
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Numbers whose base-4 and base-7 expansions have no digits in
 * common.  No closed form is known; the sequence is generated by brute-force
 * testing each integer for the digit-intersection property. */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/no_common_digits_idx.h"

/* External linkage function required by the build. */
seq_t a(idx_t n)
{
    /* Static cache of computed terms. */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static idx_t next_candidate = 1;

    /* Populate the cache until we have at least n terms. */
    while (cache_len < n) {
        /* Grow cache storage if necessary. */
        if (cache_cap == 0) {
            cache_cap = 64;
            cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            if (!cache) return 0;
        }
        if (no_common_digits_idx(next_candidate)) {
            if (cache_len == cache_cap) {
                cache_cap *= 2;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                if (!cache) return 0;
            }
            cache[cache_len++] = (seq_t)next_candidate;
        }
        ++next_candidate;
    }

    return cache[n - 1];
}
